for slug, secs in T.items():
    data = dict(slug=slug, kind="sites", narrated_only=True,
                sections=[dict(id=i, title=t, parts=p) for i, t, p in secs])
    p = os.path.join(ROOT, "audio", "scripts", "sites-%s.tashkeel.json" % slug)
    open(p, "w", encoding="utf-8").write(json.dumps(data, ensure_ascii=False, indent=1))
    print("wrote", os.path.basename(p), sum(len(x) for _, _, ps in secs for x in ps), "chars")
